-- Attendance backfill for client_id=10 branch_id=27
-- Window: 2026-02-25 .. 2026-06-24 (weekdays Mon-Fri only)
-- Employees: 36
-- Safe to re-run: attendances use ON CONFLICT DO NOTHING; punches guarded by NOT EXISTS.
BEGIN;

ON CONFLICT (employee_id, attendance_date) DO NOTHING;

-- Check In punches (direction in)
SELECT a.id, a.employee_id, a.check_in_at, 'in', 'Check In', 'manual', NOW(), NOW()
FROM attendances a
WHERE a.client_id = 10 AND a.branch_id = 27
  AND a.employee_id IN (109,108,107,104,100,99,98,97,96,94,93,92,91,90,89,88,87,86,85,84,83,82,81,80,79,78,77,76,75,74,73,72,71,70,69,68)
  AND a.attendance_date BETWEEN '2026-02-25' AND '2026-06-24'
  AND a.check_in_at IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM attendance_punches p WHERE p.attendance_id = a.id AND p.direction = 'in');

-- Check Out punches (direction out)
SELECT a.id, a.employee_id, a.check_out_at, 'out', 'Check Out', 'manual', NOW(), NOW()
FROM attendances a
WHERE a.client_id = 10 AND a.branch_id = 27
  AND a.employee_id IN (109,108,107,104,100,99,98,97,96,94,93,92,91,90,89,88,87,86,85,84,83,82,81,80,79,78,77,76,75,74,73,72,71,70,69,68)
  AND a.attendance_date BETWEEN '2026-02-25' AND '2026-06-24'
  AND a.check_out_at IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM attendance_punches p WHERE p.attendance_id = a.id AND p.direction = 'out');

COMMIT;
-- rows: 3096 attendances
